B.aGt=new A.eo("Sat\u0131n al\u0131nan krediler iade edilemez",null)
B.aJS=new A.iF("Kabul Edilebilir Kullan\u0131m",null)
B.aIv=new A.ih("Uygulamay\u0131 yaln\u0131zca ki\u015fisel mekan analizi ama\xe7l\u0131 kullanabilirsiniz. A\u015fa\u011f\u0131daki davran\u0131\u015flar yasakt\u0131r:",null)
B.aGs=new A.eo("Uygulamay\u0131 k\xf6t\xfcye kullanmak veya ba\u015fkalar\u0131n\u0131n kullan\u0131m\u0131n\u0131 engellemek",null)
B.aGl=new A.eo("Otomatik botlar veya scraper kullanmak",null)
B.aGo=new A.eo("Uygulamay\u0131 s\u0131nav s\u0131ras\u0131nda kopya \xe7ekmek i\xe7in kullanmak",null)
